def _move_case_report_files(apps, _schema_editor):
    """ Documents move from MEDIA_ROOT (served by nginx) to the private upload storage under the same relative name,
        so the rows don't change. What's left under media case_reports belonged to deleted reports """
    if settings.UNIT_TEST:  # the test database has no reports, so everything on disk would look orphaned
        return
    CaseReport = apps.get_model("classification", "CaseReport")
    for pdf_file, docx_file in CaseReport.objects.values_list("pdf_file", "docx_file"):
        for name in (pdf_file, docx_file):
            if not name:
                continue
            source = os.path.join(settings.MEDIA_ROOT, name)
            destination = os.path.join(settings.UPLOAD_DIR, name)
            if os.path.exists(source) and not os.path.exists(destination):
                os.makedirs(os.path.dirname(destination), exist_ok=True)
                shutil.move(source, destination)

    media_case_reports = os.path.join(settings.MEDIA_ROOT, CASE_REPORTS_DIR)
    if os.path.isdir(media_case_reports):
        shutil.rmtree(media_case_reports)


